CREATE TABLE roles (id TINYINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(60) NOT NULL);
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, role_id TINYINT UNSIGNED NOT NULL, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, name VARCHAR(120) NOT NULL, email VARCHAR(160) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE extracurricular_groups (id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL);
CREATE TABLE extracurriculars (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, group_id SMALLINT UNSIGNED NOT NULL, name VARCHAR(100) NOT NULL, slug VARCHAR(110) NOT NULL UNIQUE, description TEXT NOT NULL, color VARCHAR(16) NOT NULL DEFAULT '#2563eb', FOREIGN KEY(group_id) REFERENCES extracurricular_groups(id));
CREATE TABLE positions (id TINYINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(50) NOT NULL UNIQUE);
CREATE TABLE memberships (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, extracurricular_id INT UNSIGNED NOT NULL, position_id TINYINT UNSIGNED NOT NULL, status ENUM('active','inactive') NOT NULL DEFAULT 'active', UNIQUE KEY uq_membership(user_id,extracurricular_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(extracurricular_id) REFERENCES extracurriculars(id), FOREIGN KEY(position_id) REFERENCES positions(id));
CREATE TABLE staff_assignments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, extracurricular_id INT UNSIGNED NOT NULL, UNIQUE KEY uq_assignment(user_id,extracurricular_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(extracurricular_id) REFERENCES extracurriculars(id));
CREATE TABLE activities (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, extracurricular_id INT UNSIGNED NOT NULL, title VARCHAR(160) NOT NULL, activity_date DATE NOT NULL, activity_time TIME NULL, location VARCHAR(160) NULL, material VARCHAR(255) NULL, instructor VARCHAR(120) NULL, description TEXT NULL, created_by INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(extracurricular_id) REFERENCES extracurriculars(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE attendance_sessions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, activity_id INT UNSIGNED NOT NULL, token CHAR(6) NOT NULL, expires_at DATETIME NOT NULL, created_by INT UNSIGNED NOT NULL, FOREIGN KEY(activity_id) REFERENCES activities(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE attendance_records (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, session_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, status ENUM('present','excused','absent') DEFAULT 'present', checked_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_attendance(session_id,user_id), FOREIGN KEY(session_id) REFERENCES attendance_sessions(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE journals (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, extracurricular_id INT UNSIGNED NOT NULL, journal_date DATE NOT NULL, title VARCHAR(160) NOT NULL, content TEXT NOT NULL, created_by INT UNSIGNED NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(extracurricular_id) REFERENCES extracurriculars(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE proposals (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, extracurricular_id INT UNSIGNED NOT NULL, title VARCHAR(180) NOT NULL, status ENUM('draft','submitted','revision','rejected','forwarded','approved') DEFAULT 'draft', created_by INT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(extracurricular_id) REFERENCES extracurriculars(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE proposal_versions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, proposal_id INT UNSIGNED NOT NULL, version_no SMALLINT NOT NULL, file_path VARCHAR(255) NULL, notes TEXT NULL, created_by INT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_proposal_version(proposal_id,version_no), FOREIGN KEY(proposal_id) REFERENCES proposals(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE proposal_reviews (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, proposal_id INT UNSIGNED NOT NULL, reviewer_id INT UNSIGNED NOT NULL, action VARCHAR(30) NOT NULL, notes TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(proposal_id) REFERENCES proposals(id), FOREIGN KEY(reviewer_id) REFERENCES users(id));
CREATE TABLE financial_transactions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, extracurricular_id INT UNSIGNED NOT NULL, transaction_date DATE NOT NULL, type ENUM('income','expense') NOT NULL, description VARCHAR(255) NOT NULL, amount DECIMAL(14,2) NOT NULL, proof_path VARCHAR(255) NULL, created_by INT UNSIGNED NOT NULL, FOREIGN KEY(extracurricular_id) REFERENCES extracurriculars(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE news (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(180) NOT NULL, excerpt TEXT NOT NULL, published_at DATE NOT NULL, is_public BOOLEAN DEFAULT 1);
CREATE TABLE achievements (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, extracurricular_id INT UNSIGNED NOT NULL, title VARCHAR(180) NOT NULL, achievement_date DATE NOT NULL, FOREIGN KEY(extracurricular_id) REFERENCES extracurriculars(id));
CREATE TABLE score_rules (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, points INT NOT NULL, is_demo BOOLEAN DEFAULT 1);
CREATE TABLE scores (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, extracurricular_id INT UNSIGNED NOT NULL, rule_id INT UNSIGNED NOT NULL, points INT NOT NULL, note VARCHAR(255), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(extracurricular_id) REFERENCES extracurriculars(id), FOREIGN KEY(rule_id) REFERENCES score_rules(id));
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NULL, action VARCHAR(150) NOT NULL, details VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
